package io.knowledgebrain.gateway;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import org.springframework.web.server.ResponseStatusException;
class GitHubProxyTest {GatewayProxyTest f;String id="019a0000-0000-7000-8000-000000000001",root="/api/spaces/"+id+"/github/repositories";@BeforeEach void setup()throws Exception{f=new GatewayProxyTest();f.prepare();}@AfterEach void clean(){f.stop();}
 @Test void privateGetFiltersAreStrictAndNoCallerIdentityHeaderIsTrusted()throws Exception{var valid=f.request("GET",root);valid.setQueryString("state=RETIRED&limit=20&after="+id);assertEquals(200,f.gateway.proxy(valid).getStatusCode().value());assertFalse(f.headers.get().containsKey("Authorization"));for(String query:java.util.List.of("state=PUBLIC","authorId="+id,"state=ACTIVE&state=RETIRED","limit=101","after=invalid","limit=20&")){var r=f.request("GET",root);r.setQueryString(query);assertThrows(ResponseStatusException.class,()->f.gateway.proxy(r));}assertEquals(1,f.requests.get());}
 @Test void writesNeedSingletonOpaqueIntentKeyAndReadBodiesAreRejectedBeforeTransport(){var r=f.request("POST",root+"/"+id+"/sync");r.setContentType("application/json");r.setContent("{}".getBytes());assertThrows(ResponseStatusException.class,()->f.gateway.proxy(r));var body=f.request("GET",root);body.setContent("{}".getBytes());assertThrows(ResponseStatusException.class,()->f.gateway.proxy(body));assertEquals(0,f.requests.get());}}
